// Generated by build_shared_frontend.py; one physical triangle pool.
`timescale 1ns/1ps
// Runtime-exclusive frontends, one payload pool. No extra data/align register.
// Legacy native effective timing and v1 row timing both remain unchanged.
module sxm_triangle_full_core #(
  parameter integer T=4, TIMER_BITS=16, PORT_STREAMS=16,
  localparam integer RAW_BITS=((240+8*T*(T<4?5:$clog2(8*T))+8+(T<4?3:$clog2(T)+1)+31)/32)*32
) (
  input wire clk_i, rst_ni,
  // op 1: context, 2: private tile config, 3: reserve input stripe.
  // op3 data[7:0] is a source-slot mask (0 means all T for C814).
  // Explicit partial reservation lets a single vector finish independently.
  input wire ctrl_valid_i,
  input wire [1:0] ctrl_op_i,
  input wire ctrl_ctx_i,
  input wire [2:0] ctrl_index_i,
  input wire [127:0] ctrl_data_i,
  input wire cap_valid_i, cap_ctx_i,
  input wire [2:0] cap_tile_i, cap_group_i,
  input wire [3:0] cap_row_i, // 0..7 row, 8 = complete block
  input wire p_valid_i, p_ctx_i,
  input wire [2:0] p_dest_i, p_source_i,
  input wire [3:0] p_row_i, // 8 = block; 9..15 = consume row 0..6
  input wire p_paired_i, p_branch_i,
  input wire [5:0] p_sequence_i,
  // Finite per-tile output program. First send = launch + delay + 1.
  input wire [T-1:0] run_valid_i,
  input wire run_ctx_i,
  input wire [TIMER_BITS-1:0] run_delay_i, run_interval_i,
  input wire [5:0] run_count_i, run_sequence_i,
  output wire [T*PORT_STREAMS*6-1:0] sr_read_req_o,
  input wire [T*PORT_STREAMS-1:0] sr_read_valid_i,
  input wire [T*PORT_STREAMS*64-1:0] sr_read_data_i,
  output wire [T*PORT_STREAMS-1:0] sr_consume_o,
  output wire [T*PORT_STREAMS-1:0] sr_write_valid_o,
  output wire [T*PORT_STREAMS*6-1:0] sr_write_sel_o,
  output wire [T*PORT_STREAMS*64-1:0] sr_write_data_o,
  output wire [3:0] fault_o, // ctrl, capture, P, output program
  output wire busy_o,
  input wire compat_t_valid_i, compat_p_valid_i,
  input wire [1:0] compat_t_family_i, compat_p_family_i,
  input wire [RAW_BITS-1:0] compat_t_raw_i, compat_p_raw_i,
  output wire [3:0] compat_fault_o,
  input wire batch_job_i,
  input wire [1:0] batch_mode_i,batch_dtype_i,
  input wire [15:0] batch_count_i,
  input wire [T*24-1:0] batch_lane_map_i,
  input wire [T*$clog2(T)-1:0] batch_tile_map_i,
  output wire batch_ready_o,batch_fault_o,
  input wire [T-1:0] batch_cap_valid_i,
  input wire [T*8-1:0] batch_lane_valid_i,
  input wire [T*2048-1:0] batch_cap_data_i,
  output wire [T-1:0] batch_cap_accept_o,
  input wire [T-1:0] batch_block_ready_i,
  output wire [T-1:0] batch_block_valid_o,batch_block_fp32_o,batch_block_vector_o,
  output wire [T*2048-1:0] batch_block_data_o,
  output wire [T*16-1:0] batch_block_matrix_o,
  output wire [T*$clog2(T)-1:0] batch_block_column_o
);
  wire row_busy,legacy_busy,typed_busy,typed_ready;
  localparam integer SLOTS=T*(T+1)/2;
  wire [SLOTS*8-1:0] pool_wr;
  wire [SLOTS*2048-1:0] pool_rd,pool_wd;
  wire batch_any=batch_job_i || (|batch_cap_valid_i);
  wire typed_accept=!row_busy && !legacy_busy && !row_any && !legacy_any;
  assign batch_ready_o=typed_ready && typed_accept;

  wire row_any=ctrl_valid_i || cap_valid_i || p_valid_i || (|run_valid_i);
  wire legacy_any=compat_t_valid_i || compat_p_valid_i;
  wire row_accept=!typed_busy && !batch_job_i && !legacy_busy && (!legacy_any || row_busy);
  wire legacy_accept=!typed_busy && !batch_job_i && !row_busy && !(row_any && !legacy_busy);
  wire use_legacy=legacy_busy || (legacy_any && !row_busy && !row_any && !typed_busy && !batch_job_i);
  wire arbitration_fault=(row_any && !row_accept) || (legacy_any && !legacy_accept) || (batch_any && !typed_accept);
  wire [T*PORT_STREAMS*6-1:0] row_req,legacy_req,row_wsel,legacy_wsel;
  wire [T*PORT_STREAMS-1:0] row_consume,legacy_consume,row_wvalid,legacy_wvalid;
  wire [T*PORT_STREAMS*64-1:0] row_wdata,legacy_wdata;
  wire [T*1024-1:0] bank_wdata,bank_rdata,old_rdata,old_wdata;
  wire [T*16-1:0] old_rvalid,old_consume,old_wvalid;
  wire [T*96-1:0] old_req,old_wsel;
  for(genvar t=0;t<T;t=t+1) begin:g_legacy_ports
    assign old_rdata[t*1024+:1024]=sr_read_data_i[t*PORT_STREAMS*64+:1024];
    assign old_rvalid[t*16+:16]=sr_read_valid_i[t*PORT_STREAMS+:16];
    assign legacy_req[t*PORT_STREAMS*6+:PORT_STREAMS*6]={{((PORT_STREAMS-16)*6){1'b0}},old_req[t*96+:96]};
    assign legacy_wsel[t*PORT_STREAMS*6+:PORT_STREAMS*6]={{((PORT_STREAMS-16)*6){1'b0}},old_wsel[t*96+:96]};
    assign legacy_wvalid[t*PORT_STREAMS+:PORT_STREAMS]={{(PORT_STREAMS-16){1'b0}},old_wvalid[t*16+:16]};
    assign legacy_consume[t*PORT_STREAMS+:PORT_STREAMS]={{(PORT_STREAMS-16){1'b0}},old_consume[t*16+:16]};
    assign legacy_wdata[t*PORT_STREAMS*64+:PORT_STREAMS*64]={{((PORT_STREAMS-16)*64){1'b0}},old_wdata[t*1024+:1024]};
  end
  wire [T*8-1:0] bank_wr;
  wire [3:0] row_fault;
  wire [2:0] legacy_fault;
  assign sr_read_req_o=use_legacy?legacy_req:row_req;
  assign sr_consume_o=use_legacy?legacy_consume:row_consume;
  assign sr_write_valid_o=use_legacy?legacy_wvalid:row_wvalid;
  assign sr_write_sel_o=use_legacy?legacy_wsel:row_wsel;
  assign sr_write_data_o=use_legacy?legacy_wdata:row_wdata;
  assign fault_o=row_fault;
  assign compat_fault_o={arbitration_fault,legacy_fault};
  assign busy_o=row_busy || legacy_busy || typed_busy;
  sxm_triangle_row_frontend #(.T(T),.TIMER_BITS(TIMER_BITS),.COMPAT_STORAGE(0),.PORT_STREAMS(PORT_STREAMS)) u_core(
    .clk_i(clk_i),
    .rst_ni(rst_ni),
    .ctrl_valid_i(ctrl_valid_i && row_accept),
    .ctrl_op_i(ctrl_op_i),
    .ctrl_ctx_i(ctrl_ctx_i),
    .ctrl_index_i(ctrl_index_i),
    .ctrl_data_i(ctrl_data_i),
    .cap_valid_i(cap_valid_i && row_accept),
    .cap_ctx_i(cap_ctx_i),
    .cap_tile_i(cap_tile_i),
    .cap_group_i(cap_group_i),
    .cap_row_i(cap_row_i),
    .p_valid_i(p_valid_i && row_accept),
    .p_ctx_i(p_ctx_i),
    .p_dest_i(p_dest_i),
    .p_source_i(p_source_i),
    .p_row_i(p_row_i),
    .p_paired_i(p_paired_i),
    .p_branch_i(p_branch_i),
    .p_sequence_i(p_sequence_i),
    .run_valid_i(run_valid_i & {T{row_accept}}),
    .run_ctx_i(run_ctx_i),
    .run_delay_i(run_delay_i),
    .run_interval_i(run_interval_i),
    .run_count_i(run_count_i),
    .run_sequence_i(run_sequence_i),
    .sr_read_req_o(row_req),
    .sr_read_valid_i(sr_read_valid_i),
    .sr_read_data_i(sr_read_data_i),
    .sr_consume_o(row_consume),
    .sr_write_valid_o(row_wvalid),
    .sr_write_sel_o(row_wsel),
    .sr_write_data_o(row_wdata),
    .fault_o(row_fault),
    .busy_o(row_busy),
    .compat_write_rows_i('0),
    .compat_write_data_i('0),
    .compat_read_data_o(),.pool_read_i(pool_rd),.pool_write_rows_o(pool_wr),.pool_write_data_o(pool_wd));
  sxm_compat_engine #(.T(T)) u_legacy(
    .clk_i,.rst_ni,.t_valid_i(compat_t_valid_i && legacy_accept),
    .p_valid_i(compat_p_valid_i && legacy_accept),
    .t_family_i(compat_t_family_i),.p_family_i(compat_p_family_i),
    .t_raw_i(compat_t_raw_i),.p_raw_i(compat_p_raw_i),
    .read_req_o(old_req),.read_valid_i(old_rvalid),.read_data_i(old_rdata),
    .consume_o(old_consume),.write_valid_o(old_wvalid),
    .write_sel_o(old_wsel),.write_data_o(old_wdata),
    .bank_write_rows_o(bank_wr),.bank_write_data_o(bank_wdata),.bank_read_data_i(bank_rdata),
    .fault_o(legacy_fault),.busy_o(legacy_busy));

  sxm_triangle_core #(.T(T),.TIMER_BITS(TIMER_BITS),.COMPAT_STORAGE(1),.SHARED_ROW(1)) u_storage(
    .clk_i,.rst_ni,.job_valid_i(batch_job_i && typed_accept),.mode_i(batch_mode_i),.dtype_i(batch_dtype_i),.count_i(batch_count_i),
    .lane_map_i(batch_lane_map_i),.tile_map_i(batch_tile_map_i),.job_ready_o(typed_ready),
    .cap_valid_i(batch_cap_valid_i & {T{typed_accept}}),.cap_lane_valid_i(batch_lane_valid_i),.cap_data_i(batch_cap_data_i),.cap_accept_o(batch_cap_accept_o),
    .block_ready_i(batch_block_ready_i),.block_valid_o(batch_block_valid_o),.block_fp32_o(batch_block_fp32_o),.block_vector_o(batch_block_vector_o),
    .block_data_o(batch_block_data_o),.block_matrix_o(batch_block_matrix_o),.block_column_o(batch_block_column_o),.busy_o(typed_busy),.fault_o(batch_fault_o),
    .compat_write_rows_i(bank_wr),.compat_write_data_i(bank_wdata),.compat_read_data_o(bank_rdata),
    .pool_write_rows_i(pool_wr),.pool_write_data_i(pool_wd),.pool_read_o(pool_rd));

`ifndef SYNTHESIS
  always @(posedge clk_i) if(rst_ni) begin
    if((row_busy && legacy_busy) || (typed_busy && (row_busy || legacy_busy))) $fatal(1,"SXM payload ownership overlap");
    if(row_busy && |bank_wr) $fatal(1,"legacy write during row ownership");
  end
`endif
endmodule
